INSERT INTO public.document_files (id,document_id,file_type,storage_path,download_filename,mime_type,file_size,sha256,page_count,is_downloadable,download_block_reason)
SELECT (x->>'id')::uuid,(x->>'document_id')::uuid,x->>'file_type',x->>'storage_path',x->>'download_filename',x->>'mime_type',(x->>'file_size')::bigint,x->>'sha256',(x->>'page_count')::integer,(x->>'is_downloadable')::boolean,x->>'download_block_reason'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x LIMIT 60
ON CONFLICT DO NOTHING;

WITH payload AS (SELECT $archive_payload$[]$archive_payload$::jsonb AS data)
INSERT INTO public.duplicate_candidates (id,document_id,matched_external_id,match_type,similarity_score,decision,reason)
SELECT (x->>'id')::uuid,(x->>'document_id')::uuid,x->>'matched_external_id',x->>'match_type',(x->>'similarity_score')::numeric,x->>'decision',x->>'reason'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x LIMIT 100
ON CONFLICT (id) DO NOTHING;

